function setZenMode(e,t){document.body.classList.toggle("zen-mode-enable",t),document.querySelector(".toc-right")?.classList.toggle("lg:block",!t),document.querySelector(".toc-inside")?.classList.toggle("lg:hidden",!t);const n=document.querySelector(".article-content");n.classList.toggle("max-w-fit",t),n.classList.toggle("max-w-prose",!t);const s=t?"data-title-i18n-enable":"data-title-i18n-disable";e.setAttribute("title",e.getAttribute(s))}window.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("zen-mode-button");if(!e)return;setZenMode(e,!0),e.addEventListener("click",t=>{t.preventDefault();const n=!document.body.classList.contains("zen-mode-enable");if(setZenMode(e,n),n){const e=document.getElementById("single_header");window.scrollTo(window.scrollX,e.getBoundingClientRect().top-90)}else document.body.scrollIntoView()})})